"use strict";

const { spawn: spawnProcess } = require("node:child_process");

const SIGNAL_NUMBERS = {
  SIGHUP: 1,
  SIGINT: 2,
  SIGQUIT: 3,
  SIGKILL: 9,
  SIGTERM: 15,
};

class AndroidTerminal {
  constructor(file, args, options) {
    this._dataListeners = new Set();
    this._exitListeners = new Set();
    this._exited = false;
    this._exitCode = null;
    this._signal = 0;
    this._process = spawnProcess(file, args, {
      cwd: options && options.cwd,
      env: options && options.env,
      stdio: ["pipe", "pipe", "pipe"],
      windowsHide: true,
    });
    this.pid = this._process.pid;

    const emitData = (chunk) => {
      const text = Buffer.isBuffer(chunk) ? chunk.toString("utf8") : String(chunk);
      for (const listener of this._dataListeners) listener(text);
    };
    this._process.stdout.on("data", emitData);
    this._process.stderr.on("data", emitData);
    this._process.on("error", (error) => {
      emitData(`${error.message}\r\n`);
      this._finish(null, 0);
    });
    this._process.on("close", (code, signal) => {
      this._finish(code, SIGNAL_NUMBERS[signal] || 0);
    });
  }

  _finish(code, signal) {
    if (this._exited) return;
    this._exited = true;
    this._exitCode = code === null ? 0 : code;
    this._signal = signal || 0;
    for (const listener of this._exitListeners) {
      listener({ exitCode: this._exitCode, signal: this._signal });
    }
  }

  onData(listener) {
    this._dataListeners.add(listener);
    return { dispose: () => this._dataListeners.delete(listener) };
  }

  onExit(listener) {
    this._exitListeners.add(listener);
    if (this._exited) {
      queueMicrotask(() => listener({ exitCode: this._exitCode, signal: this._signal }));
    }
    return { dispose: () => this._exitListeners.delete(listener) };
  }

  write(data) {
    if (!this._exited) this._process.stdin.write(data);
  }

  resize() {}

  kill(signal) {
    if (!this._exited) this._process.kill(signal || "SIGTERM");
  }
}

function spawn(file, args, options) {
  return new AndroidTerminal(file, args, options);
}

module.exports = { spawn };
